import {mountLab} from './lab-ui.js';
import {DIFFICULTIES,ORDERS,FORMATIONS,normalizeTactics,setTactics,role} from './tactics.js';
import {conditionList,channel,incapacitated,immobilized} from './conditions.js';
import {KEYS,NAMES,balanced,valid,total,derived,newBattle,actor,alive,dist,budget,pathCheck,move,act,canAct,aiTurn,ACTIONS,efficiencies,previewAction,MOVEMENT_MODES,routeTo,fitPath,directReach,face,engaged,ENGAGEMENT_REACH,engagementReady,facingArc,phase,timelineRows,REACTIONS,setReaction,stepTimeline,previewMoveTiming,combatDefense,DAMAGE_TYPES,exertion,recoveryRates,forecastResources,nextEventTime,movementPosition,isMoving} from './engine.js';
import {MAPS,makeMap,MAP_TEMPLATES} from './maps.js';
import {visibleTo,canSee,groundAt,visibilityCells} from './battlefield.js';
import {clone,character,team,bounded,clean,generate,parseRoster,rosterFile} from './rosters.js';
import {snapshot,restore} from './persistence.js';
const root=document.querySelector('#app');document.body.classList.add('ascendant-mode');root.classList.add('ascendant-root');
const icon=new URL('./icons/icon-192.png',import.meta.url).href;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=()=>Array.from({length:2},(_,i)=>Array.from({length:5},(_,j)=>({name:`${i?'Enemy':'Ally'} ${j+1}`,stats:balanced(),locks:[]})));
let teams=defaults(),mapId=0,tab=0,edit=0,b=null,path=[],targetId=null,inspectId=null,push=exertion(false),auto=false,paused=false,delay=1,timer=null,view=null,mode='idle',note='',showLog=false,seedInput='';
let replayIndex=-1;
let setupTactics=normalizeTactics(),aiConfigOpen=false;
const isManual=c=>!!c&&c.team===0&&!auto&&!b?.automated?.includes(c.id);
let mapSeed=0,mapWidth=0,mapHeight=0,mapDeployment=6,mapFog=true,mapElevation=true,mapHazards=true,selectedMap=null,sightView='team';
function chosenMap(){return selectedMap??=makeMap(mapId,mapSeed,{width:mapWidth,height:mapHeight,deployment:mapDeployment,fog:mapFog,elevation:mapElevation,hazards:mapHazards});}
const visible=u=>!!u&&(!b||b.winner!==null||visibleTo(b,0,u));
function shownUnits(){return b.units.filter(visible);}
function fogMarkup(map){if(!map.fog||b.winner!==null)return '';const observer=sightView==='individual'?(b.units.find(u=>u.id===inspectId&&u.team===0)||b.units.find(u=>u.team===0&&u.hp>0)):null;return visibilityCells(b,0).filter(q=>observer?!canSee(map,observer,{x:q.x+q.w/2,y:q.y+q.h/2}):!q.visible).map(q=>`<rect x="${q.x}" y="${q.y}" width="${q.w}" height="${q.h}" fill="#091619" fill-opacity=".48" pointer-events="none"/>`).join('');}
function lastSeenMarkup(){if(!b.map.fog||b.winner!==null)return '';return Object.entries(b.contacts?.[0]||{}).filter(([id,p])=>p.hp>0&&!visible(b.units.find(u=>u.id===id))&&b.time-p.time<20).map(([id,p])=>`<g pointer-events="none"><circle cx="${p.x}" cy="${p.y}" r=".5" fill="none" stroke="#e3a39b" stroke-width=".08" stroke-dasharray=".12 .12"/><text x="${p.x}" y="${p.y+.18}" text-anchor="middle" font-size=".43" fill="#e3a39b">?</text></g>`).join('');}
function mapFeatures(map){return (map.elevation||[]).map(o=>`<g pointer-events="none"><rect x="${o.x}" y="${o.y}" width="${o.w}" height="${o.h}" rx=".35" fill="#83a6b5" fill-opacity=".16" stroke="#a2c0d2" stroke-width=".08"/><rect x="${o.x+o.ramp/2}" y="${o.y+o.ramp/2}" width="${o.w-o.ramp}" height="${o.h-o.ramp}" rx=".2" fill="none" stroke="#a2c0d2" stroke-width=".07" stroke-dasharray=".2 .15"/><text x="${o.x+o.w/2}" y="${o.y+.6}" text-anchor="middle" font-size=".46" fill="#c8e3ef">+${o.height.toFixed(1)}m</text></g>`).join('')+(map.hazards||[]).map(o=>`<g pointer-events="none"><rect x="${o.x}" y="${o.y}" width="${o.w}" height="${o.h}" fill="#e99b78" fill-opacity=".19" stroke="#ec987a" stroke-dasharray=".17 .17" stroke-width=".1"/><text x="${o.x+o.w/2}" y="${o.y+.5}" text-anchor="middle" font-size=".46" fill="#ffd0b5">${esc(o.kind)}</text></g>`).join('');}
function arenaOptions(){return `<div class="ascendant-arena-options"><label>Map variation seed<input id="ascendant-map-seed" type="number" min="0" max="4294967295" value="${mapSeed}"></label><button data-do="rollMapSeed">New variation</button><label>Width (m)<input id="ascendant-width" type="number" min="26" max="64" value="${chosenMap().w}"></label><label>Height (m)<input id="ascendant-height" type="number" min="20" max="48" value="${chosenMap().h}"></label><label>Deployment depth (m)<input id="ascendant-deployment" type="number" min="4" max="8" value="${chosenMap().zones[0].w}"></label><label><input type="checkbox" id="ascendant-fog" ${mapFog?'checked':''}> Fog of war</label><label><input type="checkbox" id="ascendant-elevation" ${mapElevation?'checked':''}> Raised terrain</label><label><input type="checkbox" id="ascendant-hazards" ${mapHazards?'checked':''}> Environmental hazards</label></div>`;}

let moveKind='run',showReach=false,showThreat=false,moveGoal=null,displayTime=0,advancedOpen=false;
let library=[],teamNames=['Team A','Team B'],initial=null,savedBattle=null,storageNote='',setupNote='',libraryOpen=false,importKind=null;
const read=k=>{try{return JSON.parse(localStorage.getItem(k));}catch{return null;}};
function store(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true;}catch{storageNote='Local storage unavailable or full. Export important data before leaving.';return false;}}
const saved=read('ascendant.setup.v1');if(saved?.teams?.length===2&&saved.teams.every(t=>Array.isArray(t)&&t.length===5&&t.every(c=>typeof c.name==='string'&&bounded(c.stats)))){teams=saved.teams.map(t=>t.map(clean));mapId=Math.max(0,Math.min(19,Number(saved.mapId)||0));teamNames=Array.isArray(saved.teamNames)&&saved.teamNames.length===2?saved.teamNames.map(v=>String(v).slice(0,32)):teamNames;seedInput=String(saved.seedInput??'');mapSeed=Number(saved.mapSeed)>>>0;mapWidth=Number(saved.mapWidth)||0;mapHeight=Number(saved.mapHeight)||0;mapDeployment=Number(saved.mapDeployment)||6;mapFog=saved.mapFog!==false;mapElevation=saved.mapElevation!==false;mapHazards=saved.mapHazards!==false;}
setupTactics=normalizeTactics(saved?.tactics);
const lib=read('ascendant.library.v1');if(Array.isArray(lib))library=lib.filter(v=>v&&typeof v.name==='string'&&(v.kind==='character'?character(v.data):v.kind==='team'&&team(v.data)));
try{const x=read('ascendant.battle.v1');if(x){restore(x);savedBattle=x;}}catch{storageNote='An incompatible saved battle could not be restored.';}
function save(){store('ascendant.setup.v1',{teams,mapId,teamNames,seedInput,mapSeed,mapWidth,mapHeight,mapDeployment,mapFog,mapElevation,mapHazards,tactics:setupTactics});}
function saveBattle(){if(!b)return;const x=snapshot(b,initial,{path,targetId,inspectId,push,view,mode,delay,auto,paused,moveKind,moveGoal,showReach,showThreat,sightView});if(store('ascendant.battle.v1',x))savedBattle=x;}
function resume(){if(!savedBattle)return;try{b=restore(savedBattle);initial=clone(savedBattle.initial);const u=savedBattle.ui||{};path=Array.isArray(u.path)?clone(u.path):[];targetId=u.targetId??null;inspectId=u.inspectId??b.active;push=exertion(u.push);view=u.view??null;b.paced=true;b.eventMode=false;displayTime=b.time;mode=u.mode==='route'&&actor(b)?.team===0&&!u.auto&&!b.automated?.includes(b.active)?'route':'idle';moveGoal=mode==='route'?(u.moveGoal??path.at(-1)??null):null;if(mode!=='route')path=[];moveKind=Object.hasOwn(MOVEMENT_MODES,u.moveKind)?u.moveKind:'run';showReach=u.showReach===true;showThreat=u.showThreat===true;sightView=u.sightView==='individual'?'individual':'team';delay=[.25,.5,1,2,4,8].includes(u.delay)?u.delay:1;auto=!!u.auto;paused=true;note='Saved battle restored. Clock paused until you resume.';render();}catch(e){setupNote=e.message;render();}}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function saveLibrary(kind){const data=kind==='team'?teams[tab]:teams[tab][edit];if(!(kind==='team'?team(data):character(data))){setupNote='Complete the 200-point allocation before saving.';return;}const name=kind==='team'?teamNames[tab]:data.name;library.push({kind,name,data:clone(data)});store('ascendant.library.v1',library);libraryOpen=true;setupNote=`Saved ${name} to library.`;}
function applyLibrary(index){const item=library[index];if(!item)return;if(item.kind==='team') {teams[tab]=clone(item.data);teamNames[tab]=item.name.slice(0,32);}else teams[tab][edit]=clone(item.data);save();setupNote=`Loaded ${item.name}.`;}
function rosterTools(){return `<div class="ascendant-editor-tools"><button data-do="saveCharacter">Save character</button><button data-do="copyCharacter">Duplicate to…</button><button data-do="exportCharacter">Export</button><button data-do="importCharacter">Import</button><button data-do="saveTeam">Save team</button><button data-do="copyTeam">Copy team to other side</button><button data-do="exportTeam">Export team</button><button data-do="importTeam">Import team</button><button data-do="library" class="${libraryOpen?'on':''}">Library (${library.length})</button></div><input type="file" hidden id="ascendant-import" accept=".json,application/json">${libraryOpen?`<div class="ascendant-library"><h3>Saved rosters</h3>${library.length?library.map((v,i)=>`<div class="ascendant-library-row"><span><b>${esc(v.name)}</b><small>${v.kind}</small></span><button data-load="${i}">Load</button><button data-rename="${i}">Rename</button><button data-duplicate="${i}">Copy</button><button data-delete="${i}">Delete</button></div>`).join(''):'<p class="ascendant-muted">No saved rosters yet.</p>'}</div>`:''}<p class="ascendant-message" role="status">${esc(setupNote||storageNote)}</p>`;}
function derivedPanel(s){const d=derived(s);return [['HP',d.hp],['Mana',d.mana],['Physical',d.physical],['Mental',d.mental],['Resolve',d.resolve],['Move (m)',d.move],['REA timing ref.',d.delay],['DR',d.dr],['RES (%)',d.res*100],['Mental DR',2*((s.END+s.WIL)/40)**.8],['Sight (m)',d.sight]].map(([k,v])=>`<span>${k}<b>${v.toFixed(1)}</b></span>`).join('');}
function header(sub){return `<header class="ascendant-head"><div class="ascendant-brand"><img src="${icon}" alt=""><div><h1>Ascendant <small>v1.1.11</small></h1><p>${sub}</p></div></div><div class="ascendant-head-actions">${b?'<button data-do="setup">Save & setup</button>':''}${globalThis.__APP_LAUNCHER__?'<button data-do="home">Home</button><button data-do="update" aria-label="Check updates">↻</button>':'<button data-do="update" aria-label="Check updates">↻</button>'}</div></header>`;}
function movementOverlay(c){if(!c||!b||b.moved||!showReach)return '';const p=directReach(b,path,push,moveKind,48);return p.length?`<polygon points="${p.map(q=>`${q.x},${q.y}`).join(' ')}" fill="#80d0ff" fill-opacity=".08" stroke="#8fc8e9" stroke-width=".065" stroke-opacity=".6" stroke-dasharray=".25 .14" pointer-events="none"/>`:'';}
function threatOverlay(c){if(!c||!showThreat)return '';return alive(b).filter(u=>u.team!==c.team&&visible(u)).map(u=>`<circle cx="${u.x}" cy="${u.y}" r="${ENGAGEMENT_REACH}" fill="#ec8078" fill-opacity="${engagementReady(u)?'.10':'.025'}" stroke="#ed9588" stroke-width=".07" stroke-opacity="${engagementReady(u)?'.8':'.35'}" stroke-dasharray=".25 .14" pointer-events="none"/>`).join('');}
function pathMarkup(check){if(mode!=='route'||path.length<2)return '';const col=check?.ok?'#8be6bf':'#ff9b89',end=path.at(-1);return `<polyline points="${path.map(p=>`${p.x},${p.y}`).join(' ')}" fill="none" stroke="${col}" stroke-width=".14" stroke-linejoin="round" pointer-events="none"/><circle cx="${end.x}" cy="${end.y}" r=".30" fill="${col}" stroke="#14282d" stroke-width=".08" pointer-events="none"/>`;}
function movementPanel(c,manual,check){if(mode!=='route'||!manual)return '';const mt=check?.ok?previewMoveTiming(c,check,push,moveKind):null;return `<div class="ascendant-movement-panel"><div class="ascendant-mode-grid">${Object.entries(MOVEMENT_MODES).map(([k,v])=>`<button data-movement="${k}" aria-pressed="${moveKind===k}" class="${moveKind===k?'on':''}"><b>${v.label}</b><small>${budget(c,push,k).toFixed(1)} m</small></button>`).join('')}</div><p class="ascendant-muted">Tap the battlefield to set an automatic route. ${moveKind==='walk'?'Lowest energy per metre.':moveKind==='run'?'Balanced speed and effort.':moveKind==='sprint'?'Fastest, highest energy per metre.':'Slow, guarded movement; reduced terrain penalty.'}</p><div class="ascendant-confirm-move"><div role="status">${mt?`<b>${check.length.toFixed(1)} m · ${Object.values(mt).reduce((a,b)=>a+b,0).toFixed(2)} s</b><small>Physical ${check.energy.physical.toFixed(1)} · Resolve ${check.energy.resolve.toFixed(1)} · Mental ${check.energy.mental.toFixed(1)}</small>`:esc(check?.reason||note||'Choose a destination')}</div><button data-do="move" class="ascendant-primary" ${!check?.ok?'disabled':''}>Confirm</button></div>${check?.threats?.length?`<small class="ascendant-risk">Interception risk: ${check.threats.map(t=>esc(t.name)).join(', ')}</small>`:''}${check?.hazards?.length?`<small class="ascendant-risk">Hazards: ${check.hazards.map(h=>esc(h.kind)).join(', ')}</small>`:''}</div>`;}
function clearMove(){mode='idle';path=[];moveGoal=null;note='';}
function planMove(goal){const c=actor(b);moveGoal={x:goal.x,y:goal.y};const full=routeTo(b,c,moveGoal,moveKind),p=fitPath(b,full,push,moveKind);path=p.length>1?p:[];note=path.length<2?'No traversable route.':dist(path.at(-1),moveGoal)>.03?'Route shortened to movement range.':'';}
function mapSVG(map,interactive=false){const colors={grass:'#263d35',sand:'#4a4030',stone:'#343d43',forest:'#233b35'},objects={stone:'#7b8b93',wood:'#a48960',rubble:'#6a777c',hedge:'#5e8058'},c=b&&actor(b),target=b?.units.find(u=>u.id===targetId),check=path.length>1&&b?pathCheck(b,path,push,moveKind):null;const vb=interactive&&view?`${view.x} ${view.y} ${view.w} ${view.h}`:`0 0 ${map.w} ${map.h}`;return `<svg ${interactive?'id="ascendant-board" tabindex="0" aria-label="Interactive battlefield"':'aria-label="Map preview"'} viewBox="${vb}" style="aspect-ratio:${map.w}/${map.h}" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg"><defs><pattern id="ascendant-grid" width="1" height="1" patternUnits="userSpaceOnUse"><path d="M1 0H0V1" stroke="#b1c4bc" stroke-opacity=".12" stroke-width=".035" fill="none"/></pattern></defs><rect width="${map.w}" height="${map.h}" fill="${colors[map.theme]}"/><rect width="${map.w}" height="${map.h}" fill="url(#ascendant-grid)"/>${map.zones.map((z,i)=>`<rect x="${z.x}" y="${z.y}" width="${z.w}" height="${z.h}" fill="${i?'#e5746b':'#62b5e6'}" fill-opacity=".12" stroke="${i?'#df857b':'#87c7ef'}" stroke-width=".08" stroke-dasharray=".4 .3"/><text x="${z.x+z.w/2}" y="${z.y+.9}" font-size=".65" fill="#e0e5dc" text-anchor="middle">${i?'TEAM B':'TEAM A'}</text>`).join('')}${(map.terrain||[]).map(o=>`<g pointer-events="none"><rect x="${o.x}" y="${o.y}" width="${o.w}" height="${o.h}" fill="#d4bd78" fill-opacity=".13" stroke="#d4bd78" stroke-opacity=".5" stroke-dasharray=".22 .17" stroke-width=".06"/><text x="${o.x+o.w/2}" y="${o.y+o.h/2}" text-anchor="middle" font-size=".38" fill="#ecdda7">${esc(o.kind)} ×${o.factor}</text></g>`).join('')}${mapFeatures(map)}${map.obstacles.map(o=>`<rect x="${o.x}" y="${o.y}" width="${o.w}" height="${o.h}" rx=".1" fill="${objects[o.kind]}" opacity="${o.height!==undefined&&o.height<1.2?.72:1}" stroke="#172b2c" stroke-width=".13"/><path d="M${o.x+.18} ${o.y+o.h-.18}V${o.y+.18}H${o.x+o.w-.18}" fill="none" stroke="#fff" stroke-opacity=".22" stroke-width=".10"/>`).join('')}${interactive?fogMarkup(map)+lastSeenMarkup():''}${interactive&&c&&c.team===0?(mode==='route'?movementOverlay(c):'')+threatOverlay(c):''}${interactive&&c&&visible(c)&&visible(target)?`<line x1="${c.x}" y1="${c.y}" x2="${target.x}" y2="${target.y}" stroke="#edca85" stroke-width=".08" stroke-dasharray=".25 .2"/>`:''}${interactive?shownUnits().filter(u=>u.hp>0&&u.job?.phase!=='recovery'&&u.job).map(u=>{const j=u.job,col=u.team?'#f3a29a':'#8fc8e9',t=b.units.find(v=>v.id===j.target);return j.key==='move'?(u.team===0?`<polyline data-moving-path="${u.id}" points="${[[u.x,u.y],...j.steps.slice(j.index).map(q=>[q.point.x,q.point.y])].map(q=>q.join(',')).join(' ')}" stroke="${col}" stroke-width=".10" stroke-opacity=".68" stroke-dasharray=".20 .15" fill="none" pointer-events="none"/>`:''):ACTIONS[j.key]?.reach&&t?.hp>0&&visible(t)?`<line x1="${u.x}" y1="${u.y}" x2="${t.x}" y2="${t.y}" stroke="${col}" stroke-width=".13" stroke-opacity=".65" stroke-dasharray=".15 .12" pointer-events="none"/>`:'';}).join(''):''}${interactive?shownUnits().map(u=>{const active=u.id===b.active,sel=u.id===inspectId,tar=u.id===targetId,dead=u.hp<=0,col=u.team?'#e68179':'#79c4ee';return `<g data-unit="${u.id}" data-board-unit="${u.id}" opacity="${dead?.36:1}"><circle cx="${u.x}" cy="${u.y}" r=".85" fill="transparent"/>${active?`<circle cx="${u.x}" cy="${u.y}" r=".68" fill="none" stroke="#f4e7a4" stroke-width=".13"/>`:''}${sel?`<circle cx="${u.x}" cy="${u.y}" r=".82" fill="none" stroke="#fff" stroke-width=".09"/>`:''}${tar?`<circle cx="${u.x}" cy="${u.y}" r=".96" fill="none" stroke="#ffb17b" stroke-width=".13" stroke-dasharray=".2 .12"/>`:''}<circle cx="${u.x}" cy="${u.y}" r=".48" fill="${dead?'#6c7474':col}" stroke="#102226" stroke-width=".09"/><text x="${u.x}" y="${u.y+.18}" font-size=".48" font-weight="bold" text-anchor="middle" fill="#17282b">${dead?'×':u.id.slice(1)}</text>${!dead?`<path d="M${u.x+.5*Math.cos(u.facing)} ${u.y+.5*Math.sin(u.facing)} L${u.x+.79*Math.cos(u.facing)} ${u.y+.79*Math.sin(u.facing)}" stroke="#fff5d6" stroke-width=".13" stroke-linecap="round" pointer-events="none"/>`:''}<rect x="${u.x-.55}" y="${u.y-.82}" width="1.1" height=".12" rx=".04" fill="#19282a"/><rect x="${u.x-.55}" y="${u.y-.82}" width="${1.1*u.hp/u.max.hp}" height=".12" rx=".04" fill="${col}"/>${!dead&&statusText(u)?`<circle cx="${u.x+.58}" cy="${u.y-.50}" r=".15" fill="#e5c280" stroke="#19282a" stroke-width=".04"/><title>${esc(statusText(u))}</title>`:''}</g>`;}).join(''):''}${interactive?pathMarkup(check):''}</svg>`;}
function renderSetup(){const ch=teams[tab][edit],s=ch.stats,t=total(s),all=teams.every(t=>t.every(c=>valid(c.stats)));root.innerHTML=`${header('Tactical battleground · prototype')}<div class="ascendant-resume-banner"><span>Experimental scenarios, statistics and rules</span><button data-do="lab">Simulation laboratory</button></div>${savedBattle?`<div class="ascendant-resume-banner"><span>Saved battle · turn ${savedBattle.state.turns} · seed ${savedBattle.state.seed}</span><button class="ascendant-primary" data-do="resume">Resume</button></div>`:''}<main class="ascendant-setup"><section class="ascendant-panel"><div class="ascendant-section-title"><div><span class="ascendant-kicker">01 / ROSTERS</span><h2>Assemble both teams</h2></div><span class="ascendant-pill ${all?'ok':'warn'}">${teams.flat().filter(c=>valid(c.stats)).length}/10 ready</span></div><div class="ascendant-tabs"><button data-tab="0" class="${tab===0?'on':''}">${esc(teamNames[0])} · You</button><button data-tab="1" class="${tab===1?'on':''}">${esc(teamNames[1])} · AI</button></div><label class="ascendant-team-name">Team name <input id="ascendant-team-name" maxlength="32" value="${esc(teamNames[tab])}"></label><div class="ascendant-roster">${teams[tab].map((c,i)=>`<button data-edit="${i}" class="${edit===i?'on':''}"><b>${esc(c.name)}</b><small>${total(c.stats)} / 200 ${valid(c.stats)?'✓':''}</small></button>`).join('')}</div><div class="ascendant-editor-head"><label>Character name<input id="ascendant-name" maxlength="24" value="${esc(ch.name)}"></label><div><span class="ascendant-kicker">POINTS REMAINING</span><strong class="${t===200?'ascendant-good':'ascendant-warn'}" id="ascendant-left">${200-t}</strong></div></div><div class="ascendant-stats">${KEYS.map((k,i)=>`<div class="ascendant-stat"><label for="stat-${k}"><b>${NAMES[i]}</b><small>${k}</small></label><button class="ascendant-lock ${ch.locks?.includes(k)?'on':''}" data-lock="${k}" aria-pressed="${!!ch.locks?.includes(k)}" aria-label="${ch.locks?.includes(k)?'Unlock':'Lock'} ${NAMES[i]}">${ch.locks?.includes(k)?'Lock':'Open'}</button><button data-step="${k}" data-delta="-1" aria-label="Decrease ${NAMES[i]}">−</button><input type="number" id="stat-${k}" data-stat="${k}" min="10" max="40" value="${s[k]}" inputmode="numeric" aria-label="${NAMES[i]}"><button data-step="${k}" data-delta="1" aria-label="Increase ${NAMES[i]}">+</button></div>`).join('')}</div><div class="ascendant-buttons"><button data-do="roll">Roll 10d4 / stat</button><button data-do="balance">Balance unlocked</button><button data-do="rollTeam">Roll entire team</button></div><div class="ascendant-mini-stats ascendant-derived" id="ascendant-derived">${derivedPanel(s)}</div>${rosterTools()}<p class="ascendant-muted">Locks preserve values during dice rolls and balancing; manual editing remains available. Each character must spend exactly 200 points. Every attribute is an integer from 10 to 40. Dice rolls are normalized to the same budget.</p></section><section class="ascendant-panel"><span class="ascendant-kicker">02 / ARENA</span><h2>${esc(chosenMap().name)}</h2><div class="ascendant-map-preview">${mapSVG(chosenMap())}</div><div class="ascendant-map-row"><button data-do="prevMap" aria-label="Previous map">‹</button><select id="ascendant-map" aria-label="Choose map">${MAPS.map((m,i)=>`<option value="${i}" ${i===mapId?'selected':''}>${i+1}. ${m.name}</option>`).join('')}</select><button data-do="nextMap" aria-label="Next map">›</button><button data-do="randomMap">Random</button></div>${arenaOptions()}${tacticsSettings(setupTactics[1],1)}<p class="ascendant-muted">Low cover: translucent obstacles · blue contours: ramps/high ground · gold: difficult terrain · orange: hazards. Map geometry is public; fog conceals enemy units and their actions.</p><p class="ascendant-muted">${chosenMap().w} × ${chosenMap().h} m · ${chosenMap().obstacles.length} obstacles · ${chosenMap().terrain.length} difficult terrain zones · ${chosenMap().elevation.length} raised areas · ${chosenMap().hazards.length} hazards · random deployment.</p><label class="ascendant-seed">Optional battle seed<input id="ascendant-seed" inputmode="numeric" placeholder="Random" value="${esc(seedInput)}"></label><button class="ascendant-primary ascendant-start" data-do="start" ${all?'':'disabled'}>Begin battle</button><p class="ascendant-muted">No classes, spells, equipment or special abilities. Mana is displayed but unused in this prototype.</p></section></main>`;}
const bar=(x,max,color)=>`<span class="ascendant-bar"><i style="width:${Math.max(0,Math.min(100,100*x/max))}%;background:${color}"></i></span>`;
function roster(team){return `<div class="ascendant-team ${team?'enemy':'ally'}"><div class="ascendant-team-label">${team?'TEAM B · AI':auto?'TEAM A · AI':'TEAM A · YOU / AI'}</div>${shownUnits().filter(u=>u.team===team).map(u=>`<button data-unit="${u.id}" class="ascendant-unit ${u.id===b.active?'active':''} ${u.id===inspectId?'selected':''} ${u.id===targetId?'target':''} ${u.hp<=0?'dead':''}"><span class="ascendant-unit-id">${u.id}</span><span class="ascendant-unit-main"><b>${esc(u.name)}${u.team===0&&(auto||b.automated?.includes(u.id))?' · AI':''}</b>${bar(u.hp,u.max.hp,team?'#d77d75':'#7bc2e6')}<small>${Math.ceil(u.hp)}/${Math.ceil(u.max.hp)} HP · ${Math.max(0,u.next-b.time).toFixed(1)}s</small>${statusText(u)?`<small class="ascendant-status-line">${esc(statusText(u))}</small>`:''}</span></button>`).join('')}</div>`;}
function defenseTable(u){const profile=combatDefense(u);return `<details class="ascendant-defense-table"><summary>Damage defenses by type</summary><table><thead><tr><th>Damage type</th><th>DR</th><th>RES</th></tr></thead><tbody>${Object.entries(DAMAGE_TYPES).map(([k,n])=>`<tr><td>${n}</td><td>${profile[k].dr.toFixed(2)}</td><td>${(profile[k].res*100).toFixed(1)}%</td></tr>`).join('')}</tbody></table><small>Includes active guard; situational reactions apply at impact.</small></details>`;}
function statusText(u){const items=conditionList(u).map(x=>`${x.label} ${x.model==='discrete'?'':Math.round(x.severity)}`.trim());if(u.grappledBy)items.push('Grappled by '+u.grappledBy);if(u.grappling)items.push('Holding '+u.grappling);if(u.hp<=0)items.push(u.dead?'Dead':'Down · unconscious');return items.join(' · ');}
function statusPanel(u){const items=conditionList(u),link=u.grappledBy||u.grappling;return `<div class="ascendant-conditions"><h4>Conditions</h4>${link?`<p class="ascendant-risk">${u.grappledBy?'Grappled by':'Holding'} ${esc(link)} · movement restricted until escape, release or separation.</p>`:''}${u.hp<=0?`<p>${u.dead?'Dead':'Incapacitated at zero Health; no in-battle revival.'}</p>`:''}${items.length?items.map(x=>`<div class="ascendant-condition"><span>${esc(x.label)}</span><b>${x.model==='discrete'?'Active':Math.round(x.severity)+' / 100'}</b>${bar(x.severity,100,'#d7b46f')}<small>${x.sources.map(e=>`${e.source?esc(e.source)+' · ':''}${e.remaining===null?'until removed':e.remaining.toFixed(1)+'s'}${e.decay?' · '+(e.decayMode==='proportional'?(e.decay*100).toFixed(0)+'%':e.decay)+'/s decay':''}`).join(' | ')||'Naturally recovering'}</small></div>`).join(''):'<p class="ascendant-muted">No active conditions.</p>'}<p class="ascendant-muted">Control ${(100*channel(u,'control')).toFixed(0)}% · movement ${(100*channel(u,'movement')).toFixed(0)}% · response ${(100*channel(u,'response')).toFixed(0)}%</p></div>`;}
function details(u){if(!visible(u))return '';const e=efficiencies(u),rates=recoveryRates(u);return `<div class="ascendant-detail"><div class="ascendant-section-title"><h3>${esc(u.name)} <small>${u.id}</small></h3><span>${u.hp<=0?'Down':u.guard?'Guarding':esc(phase(u))}</span></div>${[['Health','hp','#d77d75'],['Mana','mana','#6d9de0'],['Physical','physical','#69b89b'],['Mental','mental','#aa94de'],['Resolve','resolve','#d7b46f']].map(([n,k,col])=>`<div class="ascendant-resource"><span>${n}</span>${bar(u[k],u.max[k],col)}<small>${Math.round(u[k])}/${Math.round(u.max[k])}</small></div>`).join('')}<div class="ascendant-mini-stats">${KEYS.map(k=>`<span>${k} <b>${u.stats[k]}</b></span>`).join('')}</div><p class="ascendant-muted">DR ${u.max.dr.toFixed(1)} · RES ${(100*u.max.res).toFixed(1)}% · Physical ${(e.p*100).toFixed(0)}% · Mental ${(e.m*100).toFixed(0)}% · Resolve ${(e.w*100).toFixed(0)}%${u.off>0?` · Off-balance ${u.off.toFixed(0)}`:''} · Facing ${((u.facing*180/Math.PI+360)%360).toFixed(0)}° · Intercept ${engagementReady(u)?'ready':'spent'}</p><p class="ascendant-muted">${u.hp>0?`Current recovery/s: ${rates.physical.toFixed(2)} P · ${rates.mental.toFixed(2)} M · ${rates.resolve.toFixed(2)} R · ${rates.mana.toFixed(2)} Mana`:'No recovery while down.'} · Health and Mana have no low-resource penalty.</p>${b.map.schema?`<p class="ascendant-muted">Elevation ${groundAt(b.map,u).elevation.toFixed(2)} m · Surface stability ${Math.round(groundAt(b.map,u).stability*100)}% · Ground ${esc(groundAt(b.map,u).regions.join(", ")||"ordinary")} · ${b.units.filter(v=>v.team!==u.team&&visible(v)&&canSee(b.map,u,v)).length} individually detected opponents</p>`:""}${statusPanel(u)}${defenseTable(u)}</div>`;}
function previewText(p,key){if(!p)return '';const c=p.cost,base=`${Math.round(p.effort*100)}% effort · ${Math.round(p.ef*100)}% fatigue efficiency · ${c.physical.toFixed(1)} P · ${c.mental.toFixed(1)} M · ${c.resolve.toFixed(1)} R · ${p.delay.toFixed(2)}s (prep ${p.phases.preparation.toFixed(2)} / execute ${p.phases.execution.toFixed(2)} / recover ${p.phases.recovery.toFixed(2)})`;const f=p.forecast?.end,forecast=f?` · est. after action ${f.physical.toFixed(1)} P / ${f.mental.toFixed(1)} M / ${f.resolve.toFixed(1)} R`:"";if(!p.legal)return `${base} · select an eligible target`;if(p.control)return `${Math.round(p.hit*100)}% success · ${Math.round(p.strong*100)}% critical · ${p.severityRange?`Fear ${p.severityRange.map(x=>x.toFixed(0)).join("–")} on success`:p.control==='trip'?'Knock prone':p.control==='grapple'?'Restrict both characters':'Break restraint'} · ${base}${forecast}`;if(p.hit!==null)return `${Math.round(p.hit*100)}% hit · ${Math.round(p.strong*100)}% critical · ${Math.round(p.criticalFailure*100)}% critical fail · ${key==='shove'?`≤${p.shove.toFixed(1)} m push`:`${p.expected.toFixed(1)} expected damage · ${p.min.toFixed(1)}–${p.max.toFixed(1)} on hit · blunt · ${p.expectedRaw.toFixed(1)} raw − ${p.expectedReduced.toFixed(1)} DR − ${p.expectedResisted.toFixed(1)} RES (mean per attempt)${key==='heavy'?' · 1 + 8% DR pen / 10% RES pen':''}`} · ${base}${p.position?' · '+p.position.arc+(p.position.flank?' + flank':''):''}${p.reaction?' · response: '+p.reaction:''}${forecast}`;return base+forecast+(p.recovery?` · active recovery up to ${p.recovery.physical.toFixed(1)} P / ${p.recovery.mental.toFixed(1)} M / ${p.recovery.resolve.toFixed(1)} R (+ passive recovery)`:'');}
function damageDetail(q){if(!q)return '';const f=n=>Number(n).toFixed(2);return `<div class="ascendant-damage-detail"><b>Impact: ${f(q.raw)} raw → ${f(q.damage)} final</b>${q.parts.map(p=>`<div>${DAMAGE_TYPES[p.type]}: ${f(p.raw)} raw · DR ${f(p.dr)} → ${f(p.effectiveDR)} (${f(p.allocatedDR)} allocated, ${f(p.reduced)} prevented) · RES ${f(p.res*100)}% → ${f(p.effectiveRES*100)}% (${f(p.resisted)} prevented) · ${f(p.damage)} damage. Penetration: DR ${f(p.penetration.drFlat??0)} flat / ${f(100*(p.penetration.drRatio??0))}% proportional; RES ${f(100*(p.penetration.resFlat??0))} pp / ${f(100*(p.penetration.resRatio??0))}% proportional.</div>`).join('')}</div>`;}
function logDetail(d){if(!d)return '';const f=n=>Number(n).toFixed(2);return `<div class="ascendant-log-detail">${d.attack!==undefined?`d20 ${d.attack} − d20 ${d.defense} + modifier ${f(d.modifier)} = margin ${f(d.margin)} (hit ≥0, critical ≥12, critical failure ≤−12). ${d.outcome?esc(d.outcome):''}<br>`:''}${d.precision?`Precision: attack ${f(d.precision.attack)}, evasion ${f(d.precision.defense)}, base ${f(d.precision.base)}, position ${f(d.precision.position)}, terrain ${f(d.precision.environment??0)}, attack fatigue ${f(d.precision.attackerEfficiency)}, defense fatigue ${f(d.precision.defenderEfficiency)}, guard ${f(d.precision.guard)}, focus ${f(d.precision.focus)}, action ${f(d.precision.action)}, reaction ${f(d.precision.reaction??0)}.<br>`:''}${d.breakdown?`2d6 = ${d.dice}. ${damageDetail(d.breakdown)}`:d.raw!==undefined?`2d6 = ${d.dice}; raw ${f(d.raw)}; DR ${f(d.dr)} − penetration ${f(d.penetration)}; RES ${f(d.res*100)}%; final ${f(d.damage)}.<br>`:''}${d.cost?`Action cost${d.effort!==undefined?` (${Math.round(d.effort*100)}% effort)`:""}: ${f(d.cost.physical)} P / ${f(d.cost.mental)} M / ${f(d.cost.resolve)} R. ${Number.isFinite(d.efficiency)?`Efficiency ${f(d.efficiency*100)}%; next delay ${f(d.delay)}s.`:""}`:''}${d.distance!==undefined?`Distance ${f(d.distance)} m; turn cost ${f(d.turning)} m; terrain ${f(d.terrain??0)} m; ${esc(d.movementMode??'run')}; energy ${f(d.physicalCost)} P / ${f(d.mentalCost)} M / ${f(d.resolveCost)} R.`:''}${d.reaction?` Defensive response: ${esc(d.reaction)}.`:''}${d.phases?` Preparation ${f(d.phases.preparation)}s; execution ${f(d.phases.execution)}s; recovery ${f(d.phases.recovery)}s.`:''}${d.position?` Position: ${d.position.arc}${d.position.flank?' + flank':''} (+${d.position.bonus}).`: ''}${d.intercept?` Interception: ${d.damage.toFixed(1)} damage.`:''}${d.condition?` Condition: ${esc(d.condition)}${Number.isFinite(d.severity)?' · severity '+f(d.severity):''}${d.conditionRoll?' · d20 '+d.conditionRoll+' · resistance '+f(d.resistance):''}.`:''}${d.selfOffBalance!==undefined?` Critical failure: attacker off-balance ${f(d.selfOffBalance)}.`:''}${d.recovered?` Recovered ${d.recovered.map(f).join(' / ')} P/M/R.`:''}${d.displacement!==undefined?` Displacement ${f(d.displacement)} m; off-balance ${f(d.offBalance)}.`:''}</div>`;}
let expandedLogs=new Set();
function timelinePanel(){const rows=timelineRows(b).filter(u=>visible(b.units.find(v=>v.id===u.id))),horizon=Math.max(5,...rows.map(u=>u.end-b.time)),pct=t=>100*Math.max(0,Math.min(1,(t-b.time)/horizon)),segments=[['start','prepEnd','prep'],['prepEnd','impactAt','execute'],['impactAt','end','recovery']];return `<section class="ascendant-phase-panel"><div class="ascendant-section-title"><h3>Combat timeline</h3><span>Next ${horizon.toFixed(1)} s</span></div><div class="ascendant-phase-key"><span>Preparation</span><span>Execution</span><span>Recovery</span></div>${rows.map(u=>`<div class="ascendant-phase-row"><button data-unit="${u.id}" class="${u.team?'enemy':'ally'}">${u.id}</button><div class="ascendant-phase-track">${u.key?segments.filter(([a,z])=>u[z]>b.time&&u[z]>u[a]).map(([a,z,k])=>`<i class="${k}" style="left:${pct(u[a])}%;width:${Math.max(0,pct(u[z])-pct(u[a]))}%"></i>`).join(''):`<i class="ready" style="left:${pct(u.next)}%"></i>`}</div><small>${u.key?esc(u.key+' · '+u.phase):'ready '+Math.max(0,u.next-b.time).toFixed(1)+'s'}</small></div>`).join('')}<div class="ascendant-phase-key ascendant-muted">0 s <span>${(horizon/2).toFixed(1)} s</span> ${horizon.toFixed(1)} s</div></section>`;}
function replayPanel(){if(b.map.fog&&b.winner===null)return '<p class="ascendant-muted">Full replay and raw battle export unlock when combat ends (fog of war).</p>';const frames=b.frames||[];if(!frames.length)return '';const idx=replayIndex<0?frames.length-1:Math.min(replayIndex,frames.length-1),f=frames[idx];return `<details class="ascendant-replay" ${replayIndex>=0?'open':''}><summary>Recent timeline playback · ${frames.length} frames</summary><p class="ascendant-muted">Read-only event history; does not rewind the battle.</p><div class="ascendant-buttons"><button data-do="replayPrev" ${idx===0?'disabled':''}>Previous</button><button data-do="replayNext" ${idx===frames.length-1?'disabled':''}>Next</button><button data-do="replayLive">Latest</button></div><input id="ascendant-replay" type="range" min="0" max="${frames.length-1}" value="${idx}" aria-label="Timeline history frame"><p>${f.time.toFixed(2)}s · ${esc(f.label)}</p><svg viewBox="0 0 ${b.map.w} ${b.map.h}" aria-label="Recorded battlefield position"><rect width="${b.map.w}" height="${b.map.h}" fill="#253a36"/>${b.map.obstacles.map(o=>`<rect x="${o.x}" y="${o.y}" width="${o.w}" height="${o.h}" fill="#78858a"/>`).join('')}${f.units.map((u,i)=>`<g opacity="${u.hp>0?1:.3}"><circle cx="${u.x}" cy="${u.y}" r=".55" fill="${i<5?'#79c4ee':'#e68179'}"/><text x="${u.x}" y="${u.y+.2}" font-size=".48" text-anchor="middle" fill="#102226">${esc(u.id)}</text></g>`).join('')}</svg></details>`;}
function renderBattle(){const c=actor(b),target=shownUnits().find(u=>u.id===targetId),ins=shownUnits().find(u=>u.id===inspectId)||(visible(c)?c:null),manual=isManual(c),check=path.length>1?pathCheck(b,path,push,moveKind):null,order=alive(b).filter(visible).sort((a,z)=>a.next-z.next||a.id.localeCompare(z.id));root.innerHTML=`${header(`${esc(b.map.name)} · map ${b.map.seed??0} · battle ${b.seed}`)}<main class="ascendant-battle"><section class="ascendant-panel ascendant-field"><div class="ascendant-section-title"><div><span class="ascendant-kicker">${b.winner!==null?'BATTLE COMPLETE':manual?'YOUR TURN':'SIMULATION'}</span><h2>${b.winner!==null?(b.winner===2?'Draw':b.winner===0?'Team A wins':'Team B wins'):esc(visible(c)?c.name:'Resolving timeline')}</h2></div><div class="ascendant-clock"><b>${Math.max(b.time,displayTime).toFixed(1)}s</b><small>Turn ${b.turns}</small></div></div><div class="ascendant-timeline" aria-label="Upcoming turns">${order.map(u=>`<button data-unit="${u.id}" class="${u.team?'enemy':'ally'} ${u===c?'on':''}"><b>${u.id}</b><small>${u.job?esc(u.job.key)+' · ':''}+${Math.max(0,u.next-b.time).toFixed(1)}s</small></button>`).join('')}</div><div class="ascendant-board-wrap">${mapSVG(b.map,true)}</div>${timelinePanel()}<div class="ascendant-live-actions"><div class="ascendant-section-title"><h3>Actions</h3><span>${manual?esc(c.name):b.winner!==null?'Battle finished':paused?'Clock paused':'Clock running'}</span></div>${manual?`<div class="ascendant-actions ascendant-compact-actions"><button data-do="selectMove" aria-pressed="${mode==='route'}" class="${mode==='route'?'on':''}" ${budget(c,push,moveKind)<=0?'disabled':''}>Move</button>${Object.entries(ACTIONS).map(([k,a])=>`<button data-action="${k}" title="${esc(previewText(previewAction(b,k,target,push),k))}" ${!canAct(b,k,target)?'disabled':''}>${a.label}</button>`).join('')}</div>${movementPanel(c,manual,check)}`:'<p class="ascendant-muted">Waiting for the next decision.</p>'}<div class="ascendant-target">Target: <b>${target?esc(target.name):'None'}</b>${target?'<button data-do="clearTarget">Clear</button>':''}${target&&c?` · ${dist(c,target).toFixed(1)} m`:''}</div><div class="ascendant-ai-tools ascendant-clock-tools"><label class="ascendant-toggle"><input type="checkbox" id="ascendant-auto" ${auto?'checked':''}> Auto-play both</label><button data-do="pause" ${b.winner!==null?'disabled':''}>${paused?'Resume':'Pause'}</button><label>Clock <select id="ascendant-speed">${[.25,.5,1,2,4,8].map(v=>`<option value="${v}" ${delay===v?'selected':''}>${v}×</option>`).join('')}</select></label></div><details class="ascendant-advanced" ${advancedOpen?'open':''}><summary>Combat settings and forecasts</summary><div class="ascendant-exertion"><label>Effort <select id="ascendant-effort" ${!manual?'disabled':''}>${[.5,.6,.7,.8,.9,1].map(v=>`<option value="${v}" ${Math.abs(push.effort-v)<.001?'selected':''}>${Math.round(v*100)}%${v===1?' · Full':v===.5?' · Conservative':''}</option>`).join('')}</select></label><label>Resolve support <select id="ascendant-push" ${!manual?'disabled':''}>${[['none','None'],['physical','Physical'],['mental','Mental'],['both','Both']].map(([k,n])=>`<option value="${k}" ${push.push===k?'selected':''}>${n}</option>`).join('')}</select></label><small>Lower effort conserves energy at reduced output. Resolve offsets fatigue only in relevant channels; it cannot exceed available reserves. End-of-action forecasts exclude enemy interference.</small></div><div class="ascendant-reaction"><label>Defensive reaction <select id="ascendant-reaction" ${!manual?'disabled':''}>${Object.entries(REACTIONS).map(([k,v])=>`<option value="${k}" ${c?.reaction===k?'selected':''}>${v}</option>`).join('')}</select></label><small>One reaction per turn, shared with interception. Dodge evades; block absorbs; parry deflects; brace hardens; counter retaliates. Rear attacks and committed strikes can prevent responses.</small></div><div class="ascendant-actions">${Object.entries(ACTIONS).filter(([k])=>manual&&canAct(b,k,target)).map(([k,a])=>`<span><b>${a.label}</b><small>${esc(previewText(previewAction(b,k,target,push),k))}</small></span>`).join('')}</div><div class="ascendant-buttons"><button data-do="modeFace" class="${mode==='face'?'on':''}" ${!manual?'disabled':''}>Face</button><button data-do="resetView">Fit map</button><button data-do="centerActive">Center active</button></div><p class="ascendant-muted">${b.map.fog?"Fog enabled":"Full view"} · Drag to pan, pinch to zoom.</p><div class="ascendant-overlay-tools"><label class="ascendant-toggle"><input type="checkbox" id="ascendant-reach" ${showReach?'checked':''}> Direct reach (approx.)</label><label class="ascendant-toggle"><input type="checkbox" id="ascendant-threat" ${showThreat?'checked':''}> Threat ranges</label>${b.map.fog?`<label>Visibility shading <select id="ascendant-sight"><option value="team" ${sightView==='team'?'selected':''}>Team</option><option value="individual" ${sightView==='individual'?'selected':''}>Inspected ally</option></select></label>`:''}</div></details></div>${note&&mode!=='route'?`<p class="ascendant-message" role="status">${esc(note)}</p>`:''}<div class="ascendant-teams">${roster(0)}${roster(1)}</div></section><section class="ascendant-panel ascendant-controls"><div class="ascendant-section-title"><h3>Battle details</h3><button data-do="jumpBoard">Battlefield ↑</button></div>${tacticalPanel(ins)}${details(ins)}${replayPanel()}<div class="ascendant-section-title"><h3>Battle log</h3><button data-do="log">${showLog?'Recent':'Full log'}</button><button data-do="export" ${b.map.fog&&b.winner===null?"disabled":""}>Export</button></div><div class="ascendant-log">${b.log.filter(l=>!b.map.fog||b.winner!==null||l.visible!==false).slice(showLog?-1000:-12).map((l,i)=>({l,i:b.log.length-Math.min(b.log.length,showLog?1000:12)+i})).reverse().map(({l,i})=>l.detail?`<details data-log-id="${l.t}:${i}" ${expandedLogs.has(`${l.t}:${i}`)?'open':''}><summary><time>${l.t.toFixed(1)}s</time> ${esc(l.text)}</summary>${logDetail(l.detail)}</details>`:`<p><time>${l.t.toFixed(1)}s</time> ${esc(l.text)}</p>`).join('')||'<p>Battle has begun.</p>'}</div><div class="ascendant-buttons ascendant-restart"><button data-do="restart">Restart same seed</button><button data-do="rematch">New random seed</button></div>${storageNote?`<p class="ascendant-message">${esc(storageNote)}</p>`:''}</section></main>`;bindBoard();drawClock();schedule();}
function refreshSetup(){const c=teams[tab][edit],t=total(c.stats),n=teams.flat().filter(c=>valid(c.stats)).length;root.querySelector('#ascendant-left').textContent=200-t;root.querySelector('#ascendant-left').className=t===200?'ascendant-good':'ascendant-warn';root.querySelector('.ascendant-start').disabled=n!==10;const pill=root.querySelector('.ascendant-pill');pill.textContent=`${n}/10 ready`;pill.className='ascendant-pill '+(n===10?'ok':'warn');const tile=root.querySelector(`[data-edit="${edit}"]`);tile.querySelector('b').textContent=c.name;tile.querySelector('small').textContent=`${t} / 200 ${valid(c.stats)?'✓':''}`;root.querySelector('#ascendant-derived').innerHTML=derivedPanel(c.stats);}
function render(){const opt=root.querySelector('.ascendant-advanced');if(opt)advancedOpen=opt.open;const cfgEl=root.querySelector('.ascendant-ai-config');if(cfgEl)aiConfigOpen=cfgEl.open;const y=window.scrollY,logY=root.querySelector('.ascendant-log')?.scrollTop||0;if(b){saveBattle();renderBattle();const log=root.querySelector('.ascendant-log');if(log)log.scrollTop=logY;}else renderSetup();window.scrollTo(0,y);}
function drawClock(){const clock=root.querySelector('.ascendant-clock b');if(clock)clock.textContent=`${displayTime.toFixed(1)}s`;const board=root.querySelector('#ascendant-board');if(!board?.querySelector)return;for(const u of shownUnits()){if(!isMoving(u))continue;const p=movementPosition(u,displayTime),node=board.querySelector(`[data-board-unit="${u.id}"]`);node?.setAttribute('transform',`translate(${p.x-u.x} ${p.y-u.y})`);if(u.team===0){const line=board.querySelector(`[data-moving-path="${u.id}"]`);line?.setAttribute('points',[[p.x,p.y],...u.job.steps.slice(u.job.index).map(q=>[q.point.x,q.point.y])].map(q=>q.join(',')).join(' '));}}}
function schedule(){clearTimeout(timer);timer=null;if(!b||b.winner!==null||paused||document.hidden||isManual(actor(b))){if(b&&(isManual(actor(b))||b.winner!==null))displayTime=b.time;return;}const wall=Date.now();timer=setTimeout(()=>{if(!b||paused||document.hidden||isManual(actor(b)))return;const horizon=Math.max(displayTime,b.time)+Math.min(.15,(Date.now()-wall)/1000)*delay;let changed=false,decision=false;for(let i=0;i<120&&b.winner===null;i++){const c=actor(b);if(c){if(isManual(c)){decision=true;break;}aiTurn(b);changed=true;if(actor(b)===c)break;continue;}const next=nextEventTime(b);if(next===null||next>horizon+1e-9)break;stepTimeline(b);changed=true;}displayTime=decision||isManual(actor(b))||b.winner!==null?b.time:Math.max(b.time,horizon);if(isManual(actor(b))){newTurn();return;}if(changed)render();else {drawClock();schedule();}},32);}
function newTurn(){clearMove();moveKind='run';push=exertion(false);const c=actor(b);inspectId=visible(c)?c.id:(shownUnits().find(u=>u.team===0&&u.hp>0)?.id||inspectId);targetId=null;replayIndex=-1;displayTime=b.time;render();}
function selectUnit(id){const u=b.units.find(u=>u.id===id);if(!visible(u))return;inspectId=id;if(u&&u.team===1&&u.hp>0)targetId=id;render();}
function start(seed,replay=false){save();const selected=replay?clone(initial):clone(teams),map=replay?b.map:chosenMap();initial=selected;const tactics=replay?clone(b.tactics):clone(setupTactics),automated=replay?[...(b.automated||[])]:[];b=newBattle(selected,map,seed);b.paced=true;b.eventMode=false;displayTime=b.time;b.tactics=normalizeTactics(tactics);for(const t of b.tactics){t.order="advance";t.target=null;}b.automated=automated;view=null;paused=false;auto=false;mode='idle';moveKind='run';expandedLogs.clear();newTurn();window.scrollTo(0,0);}
function changeView(scale){const m=b.map,v=view||{x:0,y:0,w:m.w,h:m.h},w=Math.min(m.w,Math.max(6,v.w*scale)),h=w*m.h/m.w;view={x:Math.max(0,Math.min(m.w-w,v.x+(v.w-w)/2)),y:Math.max(0,Math.min(m.h-h,v.y+(v.h-h)/2)),w,h};render();}
function bindBoard(){
 const svg=root.querySelector('#ascendant-board');if(!svg)return;const pointers=new Map();let down=null,pinch=null,dragged=false;
 const manual=()=>isManual(actor(b));
 function coords(x,y){const p=svg.createSVGPoint();p.x=x;p.y=y;return p.matrixTransform(svg.getScreenCTM().inverse());}
 function current(){return view||{x:0,y:0,w:b.map.w,h:b.map.h};}
 function setView(v){const m=b.map;view={...v,x:Math.max(0,Math.min(m.w-v.w,v.x)),y:Math.max(0,Math.min(m.h-v.h,v.y))};svg.setAttribute('viewBox',`${view.x} ${view.y} ${view.w} ${view.h}`);}
 function pair(){return [...pointers.values()].slice(0,2);}
 svg.addEventListener('pointerdown',ev=>{if(ev.button>0)return;clearTimeout(timer);svg.setPointerCapture(ev.pointerId);pointers.set(ev.pointerId,{x:ev.clientX,y:ev.clientY});if(pointers.size===1){down={x:ev.clientX,y:ev.clientY,p:coords(ev.clientX,ev.clientY),id:ev.target.closest('[data-unit]')?.dataset.unit,v:{...current()}};dragged=false;}else if(pointers.size===2){const [a,z]=pair();pinch={d:Math.hypot(a.x-z.x,a.y-z.y),p:coords((a.x+z.x)/2,(a.y+z.y)/2),v:{...current()}};dragged=true;}});
 svg.addEventListener('pointermove',ev=>{if(!pointers.has(ev.pointerId))return;pointers.set(ev.pointerId,{x:ev.clientX,y:ev.clientY});if(pinch&&pointers.size===2){const [a,z]=pair(),m=b.map,d=Math.max(1,Math.hypot(a.x-z.x,a.y-z.y)),w=Math.max(6,Math.min(m.w,pinch.v.w*pinch.d/d)),h=w*m.h/m.w,mid=coords((a.x+z.x)/2,(a.y+z.y)/2),v=current();setView({x:pinch.p.x-(mid.x-v.x)*w/v.w,y:pinch.p.y-(mid.y-v.y)*h/v.h,w,h});return;}if(!down||pinch)return;if(Math.hypot(ev.clientX-down.x,ev.clientY-down.y)>5)dragged=true;if(dragged){const p=coords(ev.clientX,ev.clientY),v=current();setView({...v,x:v.x+down.p.x-p.x,y:v.y+down.p.y-p.y});}});
 function end(ev,cancel=false){if(!pointers.has(ev.pointerId))return;pointers.delete(ev.pointerId);if(pinch){if(!pointers.size){pinch=null;down=null;render();}return;}if(!down){schedule();return;}const p=coords(ev.clientX,ev.clientY),d=down;down=null;if(cancel||dragged){render();return;}const c=actor(b),q={x:p.x,y:p.y};if(mode==='face'&&manual()){if(face(b,d.id?b.units.find(u=>u.id===d.id):q))note='Facing updated.';mode='idle';render();return;}if(d.id){selectUnit(d.id);return;}if(manual()&&mode==='route'){planMove(q);render();return;}schedule();}
 svg.addEventListener('pointerup',ev=>end(ev));svg.addEventListener('pointercancel',ev=>end(ev,true));svg.addEventListener('wheel',ev=>{ev.preventDefault();changeView(ev.deltaY>0?1.15:1/1.15);},{passive:false});
}
root.addEventListener('click',ev=>{const el=ev.target.closest('button');if(!el||el.disabled)return;const d=el.dataset;if(d.order&&b){const target=d.order==='focus'?targetId:d.order==='protect'?inspectId:null;if(setTactics(b,0,{order:d.order,target})){note='Team order updated.';render();}return;}if(d.tab!==undefined){tab=+d.tab;edit=0;setupNote='';render();return;}if(d.edit!==undefined){edit=+d.edit;render();return;}if(d.lock){const c=teams[tab][edit];c.locks??=[];c.locks=c.locks.includes(d.lock)?c.locks.filter(k=>k!==d.lock):[...c.locks,d.lock];save();render();return;}if(d.load!==undefined){if(confirm('Replace the selected '+library[+d.load].kind+' with this saved roster?')){applyLibrary(+d.load);render();}return;}if(d.rename!==undefined){const v=library[+d.rename],name=prompt('Library name',v.name);if(name?.trim()){v.name=name.trim().slice(0,32);store('ascendant.library.v1',library);}render();return;}if(d.duplicate!==undefined){const v=clone(library[+d.duplicate]);v.name=(v.name+' copy').slice(0,32);library.push(v);store('ascendant.library.v1',library);render();return;}if(d.delete!==undefined){if(confirm('Delete this saved roster?')){library.splice(+d.delete,1);store('ascendant.library.v1',library);}render();return;}if(d.step){const s=teams[tab][edit].stats;s[d.step]=Math.max(10,Math.min(40,s[d.step]+Number(d.delta)));save();render();return;}if(d.movement&&b&&isManual(actor(b))&&mode==='route'&&Object.hasOwn(MOVEMENT_MODES,d.movement)){moveKind=d.movement;if(moveGoal)planMove(moveGoal);render();return;}if(d.unit&&b){selectUnit(d.unit);return;}if(d.action&&b&&isManual(actor(b))){clearMove();if(act(b,d.action,b.units.find(u=>u.id===targetId),push))newTurn();else render();return;}switch(d.do){case 'lab':clearTimeout(timer);mountLab(root,{teams,map:chosenMap(),tactics:setupTactics},()=>render());break;case 'home':clearTimeout(timer);saveBattle();globalThis.__APP_LAUNCHER__?.returnToLauncher();break;case 'update':if(globalThis.__APP_LAUNCHER__)globalThis.__APP_LAUNCHER__.runUpdateButton(el);else if(navigator.serviceWorker?.getRegistration)navigator.serviceWorker.getRegistration().then(async r=>{try{await r?.update();}finally{location.reload();}});else location.reload();break;case 'roll':case 'balance':{const c=teams[tab][edit],v=generate(c.stats,c.locks,Math.random,d.do==='balance');if(v){c.stats=v;setupNote='Allocation updated.';}else setupNote='Locked values make 200 points impossible. Unlock or change a stat.';save();render();break;}case 'rollTeam':{const values=teams[tab].map(c=>generate(c.stats,c.locks));if(values.every(Boolean)){teams[tab].forEach((c,i)=>c.stats=values[i]);setupNote='Team randomized.';}else setupNote='A character has impossible locks; no team values changed.';save();render();break;}case 'saveCharacter':case 'saveTeam':saveLibrary(d.do==='saveTeam'?'team':'character');render();break;case 'library':libraryOpen=!libraryOpen;render();break;case 'copyCharacter':{const slot=prompt('Copy current character to slot 1–5 on this team (replaces that slot).',String((edit+1)%5+1));if(slot!==null&&/^[1-5]$/.test(slot)&&+slot-1!==edit){if(confirm('Replace character in slot '+slot+'?')){teams[tab][+slot-1]=clone(teams[tab][edit]);edit=+slot-1;save();render();}}break;}case 'copyTeam':if(confirm('Replace the other team with a copy of this team?')){teams[1-tab]=clone(teams[tab]);teamNames[1-tab]=(teamNames[tab]+' copy').slice(0,32);save();render();}break;case 'exportCharacter':case 'exportTeam':{const kind=d.do==='exportTeam'?'team':'character',data=kind==='team'?teams[tab]:teams[tab][edit];if(kind==='team'?team(data):character(data))download(`ascendant-${kind}.json`,rosterFile(kind,data,kind==='team'?teamNames[tab]:data.name));else{setupNote='Only complete 200-point builds can be exported.';render();}break;}case 'importCharacter':case 'importTeam':importKind=d.do==='importTeam'?'team':'character';root.querySelector('#ascendant-import').click();break;case 'resume':resume();break;case 'rollMapSeed':mapSeed=Math.floor(Math.random()*4294967296)>>>0;selectedMap=null;save();render();break;case 'prevMap':case 'nextMap':case 'randomMap':mapId=d.do==='randomMap'?Math.floor(Math.random()*20):(mapId+(d.do==='prevMap'?19:1))%20;selectedMap=null;save();render();break;case 'start':if(savedBattle&&savedBattle.state.winner===null&&!confirm('Replace the saved battle?'))break;start(seedInput.trim()&&Number.isFinite(Number(seedInput))?Number(seedInput)>>>0:Date.now()>>>0);break;case 'setup':clearTimeout(timer);saveBattle();b=null;render();window.scrollTo(0,0);break;case 'restart':case 'rematch':if(confirm('Restart this battle with its original rosters?'))start(d.do==='restart'?b.seed:Date.now()>>>0,true);break;case 'clearTarget':targetId=null;render();break;case 'jumpActions':root.querySelector('.ascendant-controls')?.scrollIntoView({block:'start',behavior:'smooth'});break;case 'jumpBoard':root.querySelector('.ascendant-field')?.scrollIntoView({block:'start',behavior:'smooth'});break;case 'centerActive':if(!visible(actor(b)))break;{const c=actor(b);if(c){const m=b.map,w=view?.w||m.w*.65,h=w*m.h/m.w;view={x:Math.max(0,Math.min(m.w-w,c.x-w/2)),y:Math.max(0,Math.min(m.h-h,c.y-h/2)),w,h};render();}break;}case 'selectMove':if(isManual(actor(b))){if(mode==='route')clearMove();else{clearMove();mode='route';moveKind='run';}render();}break;case 'move':{if(mode!=='route'||!isManual(actor(b)))break;const r=move(b,path,push,moveKind);if(r.ok)newTurn();else{note=r.reason;render();}break;}case 'modeFace':clearMove();mode='face';render();break;case 'zoomIn':changeView(.7);break;case 'zoomOut':changeView(1/.7);break;case 'resetView':view=null;render();break;case 'pause':paused=!paused;render();drawClock();break;case 'replayPrev':case 'replayNext':replayIndex=Math.max(0,Math.min(b.frames.length-1,(replayIndex<0?b.frames.length-1:replayIndex)+(d.do==='replayPrev'?-1:1)));paused=true;render();break;case 'replayLive':replayIndex=-1;render();break;case 'log':showLog=!showLog;render();break;case 'export':if(b.map.fog&&b.winner===null)break;{const blob=new Blob([JSON.stringify({seed:b.seed,map:b.map.id,time:b.time,winner:b.winner,teams:initial,units:b.units,log:b.log,frames:b.frames,events:b.events},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`ascendant-battle-${b.seed}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}}});
root.addEventListener('input',ev=>{const el=ev.target;if(el.id==='ascendant-name'){teams[tab][edit].name=el.value;save();}if(el.id==='ascendant-seed'){seedInput=el.value;save();}if(el.id==='ascendant-team-name'){teamNames[tab]=el.value;save();root.querySelector(`[data-tab="${tab}"]`).textContent=el.value+(tab?' · AI':' · You');}if(el.dataset.stat){const n=Number(el.value);if(el.value!==''&&Number.isInteger(n)&&n>=10&&n<=40){teams[tab][edit].stats[el.dataset.stat]=n;refreshSetup();save();}}});
root.addEventListener('change',async ev=>{const el=ev.target;if(el.dataset?.aiUnit&&b){const id=el.dataset.aiUnit;if(/^A[1-5]$/.test(id)){b.automated=b.automated.filter(x=>x!==id);if(el.checked)b.automated.push(id);if(b.active===id)clearMove();render();}return;}if(el.dataset?.aiKey){const side=+el.dataset.aiSide,key=el.dataset.aiKey;if(![0,1].includes(side)||!['difficulty','formation','aggression','caution','coordination'].includes(key))return;const value=['aggression','caution','coordination'].includes(key)?Number(el.value):el.value;if(b){if(!setTactics(b,side,{[key]:value}))setTactics(b,side,{[key]:value,order:'advance',target:null});}else{setupTactics[side]=normalizeTactics([{...setupTactics[side],[key]:value}])[0];save();}render();return;}if(el.id==='ascendant-import'){const file=el.files?.[0];if(!file)return;try{if(file.size>1000000)throw Error('Roster file exceeds 1 MB.');const v=parseRoster(await file.text());if(v.kind!==importKind)throw Error('Wrong roster type.');if(confirm('Replace the selected '+v.kind+'?')){if(v.kind==='team'){teams[tab]=v.data;if(v.name)teamNames[tab]=v.name;}else teams[tab][edit]=v.data;save();setupNote='Imported '+v.kind+'.';}}catch(e){setupNote='Import failed: '+e.message;}render();return;}if(el.id==='ascendant-map'){mapId=+el.value;selectedMap=null;save();render();}else if(['ascendant-map-seed','ascendant-width','ascendant-height','ascendant-deployment','ascendant-fog','ascendant-elevation','ascendant-hazards'].includes(el.id)){if(el.id==='ascendant-map-seed')mapSeed=Number(el.value)>>>0;else if(el.id==='ascendant-width')mapWidth=Math.max(26,Math.min(64,Math.round(Number(el.value)||34)));else if(el.id==='ascendant-height')mapHeight=Math.max(20,Math.min(48,Math.round(Number(el.value)||24)));else if(el.id==='ascendant-deployment')mapDeployment=Math.max(4,Math.min(8,Math.round(Number(el.value)||6)));else if(el.id==='ascendant-fog')mapFog=el.checked;else if(el.id==='ascendant-elevation')mapElevation=el.checked;else mapHazards=el.checked;selectedMap=null;save();render();}else if(el.id==='ascendant-sight'){sightView=el.value==='individual'?'individual':'team';render();}else if(el.id==='ascendant-replay'){replayIndex=+el.value;paused=true;displayTime=b.time;render();}else if(el.id==='ascendant-reaction'){if(isManual(actor(b)))setReaction(b,el.value);render();}else if(el.id==='ascendant-reach'){showReach=el.checked;render();}else if(el.id==='ascendant-threat'){showThreat=el.checked;render();}else if(el.id==='ascendant-push'){push=exertion({...push,push:el.value});if(mode==='route'&&moveGoal)planMove(moveGoal);render();}else if(el.id==='ascendant-effort'){push=exertion({...push,effort:+el.value});if(mode==='route'&&moveGoal)planMove(moveGoal);render();}else if(el.id==='ascendant-auto'){auto=el.checked;if(auto)clearMove();displayTime=b.time;render();}else if(el.id==='ascendant-speed'){delay=+el.value;render();}else if(el.dataset.stat){const n=Number(el.value);teams[tab][edit].stats[el.dataset.stat]=Math.max(10,Math.min(40,Number.isFinite(n)&&el.value!==''?Math.round(n):20));el.value=teams[tab][edit].stats[el.dataset.stat];refreshSetup();save();}else if(el.id==='ascendant-name')refreshSetup();});render();

root.addEventListener('toggle',ev=>{const id=ev.target.dataset?.logId;if(id){if(ev.target.open)expandedLogs.add(id);else expandedLogs.delete(id);}},true);
window.addEventListener('pagehide',()=>{save();saveBattle();});
document.addEventListener('visibilitychange',()=>{if(document.hidden){clearTimeout(timer);if(b)displayTime=b.time;saveBattle();}else if(b)schedule();});
function tacticsSettings(cfg,side){const options=(values,selected)=>Object.entries(values).map(([k,n])=>`<option value="${k}" ${k===selected?'selected':''}>${n}</option>`).join('');return `<div class="ascendant-tactics-settings"><h4>${side?'Enemy':'Ally'} AI policy</h4><label>Difficulty <select data-ai-side="${side}" data-ai-key="difficulty">${options(DIFFICULTIES,cfg.difficulty)}</select></label><label>Formation <select data-ai-side="${side}" data-ai-key="formation">${options(FORMATIONS,cfg.formation)}</select></label>${['aggression','caution','coordination'].map(k=>`<label>${k[0].toUpperCase()+k.slice(1)} <select data-ai-side="${side}" data-ai-key="${k}">${[0,.25,.5,.6,.7,.75,1].map(n=>`<option value="${n}" ${Math.abs(n-cfg[k])<.001?'selected':''}>${Math.round(n*100)}%</option>`).join('')}</select></label>`).join('')}<small>Basic uses local heuristics unless given a team order; Standard coordinates; Tactical also compares attack forecasts. Same combat rules at every difficulty.</small></div>`;}
function tacticalPanel(ins){const cfg=b.tactics[0],orderTarget=shownUnits().find(u=>u.id===cfg.target),d=ins&&(!b.map.fog||ins.team===0||b.winner!==null)?b.aiDecisions?.[ins.id]:null;return `<section class="ascendant-tactical-panel"><h3>Team tactics</h3><div class="ascendant-tactic-order"><b>Order: ${ORDERS[cfg.order]}${orderTarget?' · '+esc(orderTarget.name):''}</b><div class="ascendant-buttons"><button data-order="advance" ${b.winner!==null?'disabled':''}>Advance</button><button data-order="focus" ${b.winner!==null||!shownUnits().some(u=>u.id===targetId&&u.team===1&&u.hp>0)?'disabled':''}>Focus target</button><button data-order="protect" ${b.winner!==null||!ins||ins.team!==0||ins.hp<=0?'disabled':''}>Protect inspected</button><button data-order="regroup" ${b.winner!==null?'disabled':''}>Regroup</button></div><small>Orders guide automated allies only. Select an enemy to focus or inspect an ally to protect.</small></div><div class="ascendant-automation">${b.units.filter(u=>u.team===0).map(u=>`<label class="ascendant-toggle"><input type="checkbox" data-ai-unit="${u.id}" ${auto||b.automated.includes(u.id)?'checked':''} ${auto||u.hp<=0||b.winner!==null?'disabled':''}> ${esc(u.name)} · ${role(u)}</label>`).join('')}</div><details class="ascendant-ai-config" ${aiConfigOpen?'open':''}><summary>AI configuration</summary>${tacticsSettings(cfg,0)}${tacticsSettings(b.tactics[1],1)}</details>${ins?`<div class="ascendant-ai-decision"><b>${esc(ins.name)} · ${role(ins)}</b>${d?`<p>${d.time.toFixed(2)}s · ${esc(ACTIONS[d.action]?.label||d.action)}${d.target&&shownUnits().some(u=>u.id===d.target)?' → '+esc(shownUnits().find(u=>u.id===d.target).name):''}</p><small>${esc(d.reason)}${Number.isFinite(d.effort)?' · '+Math.round(d.effort*100)+'% effort':''}${d.movement?' · '+esc(d.movement):''}</small>`:'<p class="ascendant-muted">No visible AI decision recorded.</p>'}</div>`:''}</section>`;}
